pm.collectionVariables.set("missingIdOwnerId", body.id);

// PUT devolve 204 sem corpo: não use pm.response.json() aqui
const sent = JSON.parse(pm.variables.replaceIn(pm.request.body.raw));
const ownerId = pm.collectionVariables.get("ownerId");

pm.test("status 204", () => pm.response.to.have.status(204));

pm.test("responde em menos de 500 ms", () => {
