// Sem corpo na resposta, a conferência é feita consultando o dono
pm.sendRequest(pm.environment.get("baseUrl") + "/owners/" + ownerId, (err, res) => {
  pm.test("GET do dono devolve 200", () => {
    pm.expect(err).to.be.null;
    pm.expect(res.code).to.eql(200);
  });

  const owner = res.json();

  pm.test("dono tem os novos valores enviados", () => {
    ["firstName", "lastName", "address", "city", "telephone"].forEach((field) => {
      pm.expect(owner[field], field).to.eql(sent[field]);
    });
  });

  pm.test("id continua o mesmo", () => {
    pm.expect(String(owner.id)).to.eql(String(ownerId));
  });
});

